	"Move '{arg}' is not available in Gen {dex.gen}.": "La capacité « {arg} » n'est pas disponible en Gen {dex.gen}.",
	"No moves using a type table for determining damage were specified.": "Aucune des capacités indiquées n'utilise la table des types pour calculer ses dégâts.",
	"Specify a maximum of 4 moves or types.": "Indiquez au maximum 4 capacités ou types.",
	"Coverage for {sourceList}:": "Couverture de {sourceList} :",
	"Super Effective": "Super efficace",
	"Neutral": "Neutre",
